def is_happy(n):
    slow = n
    fast = n

    while True:
        slow = digit_square_sum(slow)
        fast = digit_square_sum(fast)
        fast = digit_square_sum(fast)

        if fast == 1:
            return True
        if fast == slow:
            return False

def digit_square_sum(n):
    ans = 0
    while n > 0:
        ans += (n % 10) ** 2
        n //= 10
    return ans

def find_happy_numbers(count):
    found = 0
    number = 1
    while found < count:
        if is_happy(number):
            print(number)
            found += 1
        number += 1

