import cmath

def solve_quadratic():
    while True:
        user_input = input("Enter coefficients a, b, c (or type 'quit' to exit): ").strip()
        if user_input.lower() == 'quit':
            break

        # Splitting the input into a, b, and c
        try:
            a, b, c = map(float, user_input.split(','))
        except ValueError:
            print("Invalid input. Please enter numbers separated by commas.")
            continue

        # Calculate the discriminant
        disc = (b**2) - (4*a*c)

        # Calculate the two solutions
        sol1 = (-b-cmath.sqrt(disc))/(2*a)
        sol2 = (-b+cmath.sqrt(disc))/(2*a)

        if disc > 0:
            print("The equation has two solutions:", sol1, "and", sol2)
        elif disc == 0:
            print("The equation has one solution:", sol1)
        else:
            print("The equation has no real solutions.")

solve_quadratic()

