def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def sum_of_primes(n):
    num = 0
    sum = 0
    prime_count = 0
    while prime_count < n:
        if is_prime(num):
            sum += num
            prime_count += 1
        num += 1
    return sum

n = 10
print(f"Sum of first {n} prime numbers is {sum_of_primes(n)}")

