def evaluate_secretaries_and_administrative_assistants_except_legal_medical_and_executive(staff_list):
    total_score = 0
    number_of_staff = len(staff_list)
    scores = []

    for staff in staff_list:
        if staff['role'] not in ['legal', 'medical', 'executive']:
            score = 0

            # evaluate gender, females get higher score
            if staff['gender'] == 'female':
                score += 2

            # evaluate time management
            if staff['time_management'] >= 8:
                score += 2

            # evaluate attention to detail
            if staff['attention_to_detail'] >= 8:
                score += 2

            # evaluate multitasking
            if staff['multitasking'] == 'yes':
                score += 2

            # evaluate organization
            if staff['organization'] >= 8:
                score += 2

            total_score += score
            scores.append((staff['name'], score))

    # calculate mean score
    mean_score = total_score/number_of_staff

    # adjust score considering the mean
    adjusted_scores = []
    for name, score in scores:
        if score > mean_score:
            adjusted_score = score + 1
        else:
            adjusted_score = score
        adjusted_scores.append((name, adjusted_score))

    return adjusted_scores

